Item.method_code:
/*
  指定のパス名のパスを現在のアクティビティで非表示にする
  （オリジナルは、h4_hidePullBack）
*/

Innovator inn = this.getInnovator();

string id = this.getProperty("acId","");
string targetPathName = this.getProperty("targetPathName","");
string isVisible = "0";//非表示

string body = "<targetPathName>"+targetPathName+"</targetPathName><acId>"+id+"</acId><isVisible>"+ isVisible +"</isVisible>";
var retItem = inn.applyMethod("h4_SetPathVisibility",body);
if(retItem.isError())
{
    //エラー
    return inn.newError(retItem.getErrorString());
}

return this;
